	public class ProjectileAttackState : SkillState
	{
		private Projectile newProjectile;

		public ProjectileAttackState(string newName, FSM newFSM, Player newPlayer)
			: base(newName, newFSM, newPlayer)
		{
			isProjectileSkill = true;
		}

		public GameObject GetPrefabResource(string str)
		{
			return ChaosBundle.Get("Assets/Prefabs/Projectiles/" + str + ".prefab");
		}

		public virtual Projectile CreateProjectile(GameObject prefab, Vector3? givenPosition = null, Quaternion? givenQuaternion = null, Transform parentTrans = null, bool setAtkInfo = true)
		{
			newProjectile = Projectile.CreateProjectile(parent, prefab, (Vector2)((!givenPosition.HasValue) ? parent.attackOriginTrans.position : givenPosition.Value), (!givenQuaternion.HasValue) ? Quaternion.identity : givenQuaternion.Value, parentTrans ?? parent.transform.parent);
			if (setAtkInfo)
			{
				SetProjectileAtkInfo(newProjectile);
			}
			return newProjectile;
		}

		public virtual void FireProjectile(Projectile projectile, Vector2 moveVector, bool setKnockbackVector = true, float newMoveSpeed = 0f, float newFlyTime = 0f, string audioString = "", bool setAtkInfo = false)
		{
			projectile.transform.SetParent(null);
			if (setAtkInfo)
			{
				SetProjectileAtkInfo(projectile);
			}
			projectile.moveVector = moveVector;
			if (setKnockbackVector)
			{
				projectile.attackBox.knockbackOverwriteVector = moveVector;
			}
			if (newMoveSpeed != 0f)
			{
				projectile.moveSpeed = newMoveSpeed;
			}
			if (newFlyTime != 0f)
			{
				projectile.flyTime = newFlyTime;
				projectile.lifeTime = newFlyTime * 2f;
			}
			projectile.RefreshFlightTime();
			if (audioString != string.Empty)
			{
				SoundManager.PlayWithDistAndSPR(audioString, projectile.transform.position);
			}
		}

		public virtual void SetProjectileAtkInfo(Projectile projectile)
		{
			projectile.attackBox.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
			projectile.UpdateCalculatedDamage(initDamageOverride: true);
		}
	}

	public class ProjectileChainAttackState : ProjectileAttackState
	{
		public float shotDelay = 0.125f;

		public int shotStopwatchID;

			cooldownRef.skillState = skillState;
			cooldownRef.remainingTimeStopwatchID = -1;
			cooldownRef.delayStopwatchID = -1;
		}

		public virtual void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			empoweredStat.Modify(givenMod, givenStatus);
			if (parent.skillEmpowerEventHandlers != null)
			{
				parent.skillEmpowerEventHandlers(this);
			}
		}

		public virtual bool IsReady()
		{
			if ((isMovementSkill && !parent.MovementEnabled) || (isUltimate && !IsOverdriveReady()) || (!isUltimate && !cooldownRef.Ready))
			{
				return false;
			}
			if (allowSelfTransition && !allowRepeating && repeatLock)
			{
				return false;
			}
			return true;
		}

		public virtual bool IsOverdriveReady()
		{
			return true;
		}

		public bool Transition()
		{
			if (!IsReady() || (!allowSelfTransition && fsm.currentStateName == skillID))
			{
				return false;
			}
			fsm.ChangeState(skillID, allowSelfTransition: true);
			return true;
		}

		public int SetSkillSlot()
		{
			for (int i = 0; i < parent.assignedSkills.Length; i++)
			{
				if (parent.assignedSkills[i] != null && parent.assignedSkills[i].skillID == skillID)
				{
					skillSlot = i;
					return skillSlot;
				}
			}
			skillSlot = -1;
			return skillSlot;
		}

		public void SetRepeatLock(bool setLock = true)
		{
			repeatLock = setLock;
		}

		public void UpdateRepeatLock(string buttonName = "")
		{
			if (skillSlot != -1)
			{
				if (buttonName == string.Empty)
				{
					buttonName = "Skill" + skillSlot;
				}
				if (parent.inputDevice.GetButtonUp(buttonName))
				{
					SetRepeatLock(setLock: false);
				}
			}
		}

		public virtual void StartCooldownTimer(float overrideValue = -1f, bool expendCharge = true)
		{
			if (useSmartCD)
			{
				if (cdStarted)
				{
					return;
				}
				cdStarted = true;
			}
			if ((skillData.GetValue<float>("cooldown") == 0f && overrideValue == -1f) || parent == null || parent.gameObject == null || !parent.gameObject.activeSelf)
			{
				return;
			}
			if (isChargeSkill)
			{
				if (expendCharge && cooldownRef.chargeCount > 0)
				{
					cooldownRef.chargeCount = Mathf.Max(0, cooldownRef.chargeCount - ((!(overrideValue > 0f)) ? 1 : ((int)overrideValue)));
				}
				parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
			}
			else
			{
				parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
			}
		}

		public void ApplyStopElement()
		{
			if (parent.dotManager != null)
			{
				parent.dotManager.ApplyStopElement(element);
			}
		}

		public void BaseOnEnter()
		{
			SetRepeatLock();
			SetSkillSlot();
			if (parent.skillEnterEventHandlers != null)
			{
				parent.skillEnterEventHandlers(this);
			}
			if (fsm.previousState is SkillState)
			{
				prevSkillState = fsm.previousState as SkillState;
				if (isBasic)
				{
					if (!prevSkillState.isBasic && parent.cancelToBasicEventHandlers != null)
					{
						parent.cancelToBasicEventHandlers(this, prevSkillState);
					}
				}
				else if (prevSkillState.isBasic && parent.cancelFromBasicEventHandlers != null)
				{
					parent.cancelFromBasicEventHandlers(this, prevSkillState);
				}
				else if (isDash && parent.cancelToDashEventHandlers != null)
				{
					parent.cancelToDashEventHandlers(this, prevSkillState);
				}
			}
			cdStarted = false;
			if (!disableStartCooldown && startCooldownOnEnter)
			{
				StartCooldownTimer();
			}
			if (applyStopElementStatus)
			{
				ApplyStopElement();
			}
		}

		public override void OnEnter()
		{
			BaseOnEnter();
			inputVector = parent.GetInputVector();
			parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
			holdStarted = false;
			holdReleased = false;
			skillExecuted = false;
		}

		public override void Update()
		{
			UpdateRepeatLock(string.Empty);
			if (skillExecuted)
			{
				ConcludeSkill();
			}
			else if (isHoldSkill)
			{
				if (holdReleased)
				{
					ExecuteSkill();
				}
				else if (holdStarted)
				{
					HandleHoldButton();
				}
				else
				{
					holdStarted = parent.anim.AnimPlayed(animHoldTime);
				}
			}
			else if (parent.anim.AnimPlayed(animExecTime))
			{
				ExecuteSkill();
			}
		}

		public virtual void HandleHoldButton()
		{
			inputVector = GetInputVector();
			if (updateHoldAnim)
			{
				parent.anim.PlayDirectional(OnHoldAnimStr, -1, animHoldTime);
			}
			holdReleased = !parent.inputDevice.GetButton("Skill" + skillSlot);
		}

		public virtual void ExecuteSkill()
		{
			skillExecuted = true;
			AnnounceSkillExecuteEvent();
		}

		public virtual void AnnounceSkillExecuteEvent()
		{
			if (parent.skillExecEventHandlers != null)
			{
				parent.skillExecEventHandlers(this);
			}
		}

		public virtual void ConcludeSkill()
		{
			ExitToSkillOrRunOrIdle();
		}

		public override void OnExit()
		{
			if (allowSelfTransition && !allowRepeating && GetType() != fsm.nextState.GetType())
			{
