	public class ProjectileChainAttackState : ProjectileAttackState
	{
		public float shotDelay = 0.125f;

		public int shotStopwatchID;

		public bool attackStarted;

		public bool firstAnim;

		public bool updateInput = true;

		private Vector2 checkAimVec;

		public ProjectileChainAttackState(string newName, FSM newFSM, Player newPlayer)
			: base(newName, newFSM, newPlayer)
		{
			disableStartCooldown = true;
			isHoldSkill = true;
			InitChargeSkillSettings(skillData.GetValue<int>(StatData.spawnStr), 0f, skillData, this);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			UpdateCDCounter();
			attackStarted = false;
			firstAnim = true;
		}

		public override void HandleHoldButton()
		{
			if (!StartAttack())
			{
				return;
			}
			switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
			{
			case StopwatchState.Ready:
				if (firstAnim)
				{
					firstAnim = false;
					AnnounceSkillExecuteEvent();
				}
				else if (updateInput)
				{
					checkAimVec = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
					if (checkAimVec != Vector2.zero)
					{
						inputVector = GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false);
					}
					parent.anim.PlayDirectional(OnHoldAnimStr, -1, animExecTime);
				}
				if (cooldownRef.chargeCount > 0)
				{
					cooldownRef.chargeCount--;
				}
				if (!cooldownRef.IsCharging)
				{
					UpdateCDCounter();
				}
				FireChainProjectile();
				break;
			case StopwatchState.Done:
				skillExecuted = true;
				break;
			}
			CancelToDash();
		}

		public override void OnExit()
		{
			base.OnExit();
			StartCooldownTimer(-1f, expendCharge: false);
			ChaosStopwatch.Stop(shotStopwatchID);
		}

		public virtual void UpdateCDCounter()
		{
			StartCooldownTimer(-1f, expendCharge: false);
			ChaosStopwatch.Pause(cooldownRef.remainingTimeStopwatchID);
		}

		public virtual bool StartAttack()
		{
			if (!attackStarted)
			{
				if (!parent.anim.AnimPlayed(animExecTime))
				{
					return false;
				}
				attackStarted = true;
				shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotDelay, cooldownRef.chargeCount);
			}
			return true;
		}

		public virtual void FireChainProjectile()
		{
		}
	}

	public class ProjectileChargeAttackState(string newName, FSM newFSM, Player newPlayer) : ProjectileHoldAttackState(newName, newFSM, newPlayer)
	{
		public bool useCastBar = true;

	public class ShootBoltClaymore : ProjectileAttackState
	{
		public new static string staticID = "ShootBoltClaymore";

		private BoltClaymore currentBC;

		private string holdStr;

		public ShootBoltClaymore(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			SetAnimTimes(0.2f, 0.2f, 0.3f, 0.55f, 0.75f);
		}

		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			currentLevel = ((!IsEmpowered) ? 1 : 3);
		}

		public override bool IsReady()
		{
			return currentBC == null && base.IsReady();
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			currentBC = (BoltClaymore)CreateProjectile(BoltClaymore.Prefab, parent.attackOriginTrans.position + (Vector3)inputVector);
			currentBC.isEmpowered = IsEmpowered;
			FireProjectile(currentBC, inputVector, setKnockbackVector: false, 0f, 0f, string.Empty);
			parent.StartCoroutine(HandleDetonation());
			CameraController.ShakeCamera(0.25f);
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(4, currentBC.transform.position);
		}

		private IEnumerator HandleDetonation()
		{
			yield return Globals.waitForQuarter;
			parent.overheadPrompt.DisplayPrompt("Slot" + skillSlot, loop: true);
			holdStr = "Skill" + skillSlot;
			while (currentBC != null && !currentBC.detonated)
			{
				if (parent.inputDevice.GetButtonDown(holdStr))
				{
					currentBC.Detonate(triggered: true);
					currentBC = null;
				}
				yield return null;
			}
			currentBC = null;
			parent.overheadPrompt.HidePrompt(string.Empty);
		}
	}

