	public class UseThunderFan : ProjectileAttackState
	{
		public new static string staticID = "UseThunderFan";

		private static float parentMoveSpeed = 12f;

		private static int totalPosCount = 15;

		private int halfPosCount;

		private Vector2 attackPosition;

		private bool isFirstFan;

		private bool throwCompleted;

		private ChaosQuickStopwatch speedStopwatch = new ChaosQuickStopwatch(0.5f);

		private ThunderFanProjectile currentFP;

		private ThunderFanBall currentTB;

		public UseThunderFan(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			SetAnimTimes(0.15f, 0.2f, 0.3f, 0.5f, 0.75f);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			isFirstFan = true;
			throwCompleted = false;
			parent.movement.moveVector = inputVector;
			parent.movement.MoveToMoveVector(parentMoveSpeed);
		}

		public override void ExecuteSkill()
		{
			if (isUltimate)
			{
				ThrowThunderFanBall();
				base.ExecuteSkill();
			}
			else if (isFirstFan)
			{
				if (!throwCompleted)
				{
					throwCompleted = true;
					ThrowFan();
				}
				if (parent.anim.AnimPlayed(cancelThreshold))
				{
					isFirstFan = false;
					parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animStartTime);
					parent.movement.MoveToMoveVector(parentMoveSpeed);
				}
			}
			else
			{
				ThrowFan();
				base.ExecuteSkill();
			}
		}

		private void ThrowThunderFanBall()
		{
			currentTB = (ThunderFanBall)CreateProjectile(ThunderFanBall.Prefab);
			currentTB.attackBox.SetAttackInfo(parent.skillCategory, skillID, 1, isUltimate);
			FireProjectile(currentTB, inputVector, setKnockbackVector: true, 0f, 0f, string.Empty);
		}

		private void ThrowFan()
		{
			parent.movement.EndMovement();
			attackPosition = parent.attackOriginTrans.position;
			SoundManager.PlayWithDistAndSPR("BoltClaymore", attackPosition);
			SoundManager.PlayAudioWithDistance("BallLightningEnd", attackPosition, null, 24f, -1f, 1.25f);
			speedStopwatch.IsRunning = true;
			if (isFirstFan)
			{
				for (int i = -1; i <= 1; i++)
				{
					ThrowFanProjectile(attackPosition, Globals.GetRotatedCircleVector(totalPosCount + 2, i, inputVector));
				}
				return;
			}
			halfPosCount = Mathf.CeilToInt((float)totalPosCount * 0.5f) + 2;
			for (int j = halfPosCount - 4; j < halfPosCount; j++)
			{
				ThrowFanProjectile(attackPosition, Globals.GetRotatedCircleVector(totalPosCount, j, -inputVector));
			}
		}

		private void ThrowFanProjectile(Vector2 givenPosition, Vector2 givenVector)
		{
			currentFP = (ThunderFanProjectile)CreateProjectile(ThunderFanProjectile.Prefab, givenPosition + givenVector, Globals.GetRotationQuaternion(givenVector));
			currentFP.speedStopwatchID = speedStopwatch.ID;
			currentFP.isEmpowered = IsEmpowered;
			currentFP.empTrans = parent.attackOriginTrans;
			FireProjectile(currentFP, givenVector, setKnockbackVector: true, 0f, 0f, string.Empty);
