	}

	public static LightningBurst CreateBurst(Vector3 givenPosition, AttackInfo givenAtkInfo, float givenScale = 1f)
	{
		return (LightningBurst)ElementalBurst.CreateBurst(Prefab, givenPosition, givenAtkInfo, givenScale);
	}
}
