using UnityEngine;

public class IonSpike : MonoBehaviour
{
	private static GameObject prefab;

	private static float empRange = 1.75f;

	[HideInInspector]
	public Attack attack;

	[HideInInspector]
	public Vector2 attackVector;

	[HideInInspector]
	public float maxRange = 8f;

	private float calcRange;

	private Vector3 attackStartPosition;

	private Vector3 attackEndPosition;

	private Vector2 attackPosition;

	private ParticleEffect lightningEmitter;

	private ParticleSystem ionPartSys;

	private ParticleSystem.ShapeModule ionShapeMod;

	private ParticleSystem.EmissionModule ionEmitMod;

	private BoxCollider2D attackCollider;

	[HideInInspector]
	public int delayStopwatchID = -1;

	private int audioStopwatchID = -1;

	private int intervalStopwatchID;

	public int intervalCount = 3;

	public float intervalDelay = 0.125f;

	private SpriteRenderer orbSprite;

	private SpriteRenderer shadowSprite;

	private bool attackStarted;

	private bool attackCompleted;

	private string skillCat;

	private string skillID;

	private bool isEmpowered;

	private IonSpike currentIS;

	private Vector2 hitPosition;

	private Vector2 addVector;

	private List<Entity> hitList = new List<Entity>();

	private bool ignoreWalls;

	private FollowTransform followScript;

	private Vector2 effectPosition;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/IonSpike.prefab"));

	private void Awake()
	{
		attack = transform.Find("AttackBox").GetComponent<Attack>();
		attackCollider = attack.transform.GetComponent<BoxCollider2D>();
		ionPartSys = attack.transform.Find("IonEmitter").GetComponent<ParticleSystem>();
		ionShapeMod = ionPartSys.shape;
		ionEmitMod = ionPartSys.emission;
		orbSprite = transform.Find("OrbSprite/ProjectileSprite").GetComponent<SpriteRenderer>();
		shadowSprite = transform.Find("ShadowSprite").GetComponent<SpriteRenderer>();
		lightningEmitter = PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect");
		lightningEmitter.reqFollowTrans = true;
		ParticleEffect particleEffect = lightningEmitter;
		float? emissionRate = 0f;
		Vector3? position = orbSprite.transform.position;
		Transform followTransform = orbSprite.transform;
		ParticleSystemOverride smallFGAuraOverride = LightningAuraEffect.SmallFGAuraOverride;
		particleEffect.Play(emissionRate, position, smallFGAuraOverride, null, followTransform);
		followScript = GetComponent<FollowTransform>();
	}

	private void Start()
	{
		this.attack.transform.localEulerAngles = Globals.GetRotationVector(attackVector);
		attackStartPosition = transform.position;
		attackEndPosition = GetEndPointVector(attackVector);
		attackPosition = (attackStartPosition + attackEndPosition) * 0.5f;
		calcRange = (attackEndPosition - attackStartPosition).magnitude;
		float num = calcRange * 0.5f;
		attackCollider.size = new Vector2(0.75f, calcRange);
		attackCollider.offset = new Vector2(0f, num);
		ionPartSys.transform.position = attackPosition;
		ionShapeMod.radius = num;
		ionEmitMod.rateOverTime = 5f * calcRange;
		attackStarted = false;
		attackCompleted = false;
		SoundManager.PlayWithDistAndSPR("StaticCrackle", transform.position);
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(1, orbSprite.transform.position, LightningAuraEffect.SmallAuraOverride);
		if (isEmpowered)
		{
			Attack attack = this.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = this.attack;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
	}

	private void Update()
	{
		if (!attackStarted && ChaosStopwatch.Check(delayStopwatchID))
		{
			intervalStopwatchID = ChaosStopwatch.Begin(intervalDelay, useInterval: true, intervalDelay, intervalCount);
			attackStarted = true;
			ionPartSys.Stop();
			lightningEmitter.Stop();
			PlayEffects();
		}
	}

	private void FixedUpdate()
	{
		if (!attackStarted || attackCompleted)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(intervalStopwatchID))
		{
		case StopwatchState.Running:
			attackCollider.enabled = true;
			break;
		case StopwatchState.Ready:
			attackCollider.enabled = false;
			if (ChaosStopwatch.IntervalIsActive(intervalStopwatchID))
			{
				PlayEffects();
			}
			break;
		case StopwatchState.Done:
		{
			attackCompleted = true;
			attackCollider.enabled = false;
			orbSprite.enabled = false;
			shadowSprite.enabled = false;
			Attack attack = this.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			hitList.Clear();
			UnityEngine.Object.Destroy(gameObject, 0.25f);
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(3, orbSprite.transform.position, LightningAuraEffect.SmallAuraOverride);
			break;
		}
		}
	}

	private void PlayEffects()
	{
		effectPosition = orbSprite.transform.position;
		if (followScript.followTransform != null)
		{
			attackEndPosition = effectPosition + attackVector * empRange;
		}
		PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningLine").Emit(effectPosition, attackEndPosition);
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(1, effectPosition);
		SoundManager.PlayAudioWithDistance("IonSpike", transform.position);
		CameraController.ShakeCamera(0.25f);
	}

	private Vector2 GetEndPointVector(Vector2 givenVector)
	{
		if (ignoreWalls)
		{
			return transform.position + (Vector3)givenVector * maxRange;
		}
		return Globals.GetLinecastVector(transform.position, transform.position + (Vector3)givenVector * maxRange, ChaosCollisions.layerUpperWallAndObst);
	}

	private void OnTargetHit(Entity givenEntity)
	{
		if (!(givenEntity == null) && !(givenEntity is Destructible) && !hitList.Contains(givenEntity) && hitList.Count <= 3)
		{
			hitPosition = givenEntity.hurtBoxTransform.position;
			hitList.Add(givenEntity);
			attackPosition = UnityEngine.Random.insideUnitCircle.normalized;
			for (int i = 1; i < 6; i += 2)
			{
				addVector = Globals.GetRotatedCircleVector(6, i, attackVector);
				CreateIonSpike(hitPosition, addVector, givenEntity.hurtBoxTransform);
			}
		}
	}

	private void CreateIonSpike(Vector2 givenPosition, Vector2 givenVector, Transform givenTrans)
	{
		currentIS = Globals.ChaosInst<IonSpike>(Prefab, null, givenPosition - givenVector * empRange);
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(1, currentIS.transform.position);
		currentIS.attack.SetAttackInfo(skillCat, skillID, 2);
		currentIS.attackVector = givenVector;
		currentIS.maxRange = empRange;
		currentIS.intervalCount = 5;
		currentIS.intervalDelay = intervalDelay;
		currentIS.delayStopwatchID = ChaosStopwatch.Begin(1.125f);
		currentIS.ignoreWalls = true;
		currentIS.followScript.followTransform = givenTrans;
		currentIS.followScript.followOffset = -givenVector * empRange;
	}

	public void SetSkillInfo(string givenCategory, string givenID, bool isEmp = false)
	{
		skillCat = givenCategory;
		skillID = givenID;
		attack.SetAttackInfo(skillCat, skillID);
		isEmpowered = isEmp;
	}

	public void AbortSpike()
	{
		attackStarted = true;
		ChaosStopwatch.Stop(intervalStopwatchID);
	}
}
