using UnityEngine;

public class ThunderAnchor : ThrownItem
{
	private static GameObject prefab;

	public float lifeTime = 10f;

	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch();

	private static float maxDistance = 12.5f;

	[HideInInspector]
	public Vector2 positionOffset;

	public Transform streamTrans;

	private Transform parentTrans;

	private Health parentHealth;

	private string skillCat = string.Empty;

	private string skillID = string.Empty;

	private int burstStopwatchID;

	private int burstCount = 5;

	private float burstDelay = 0.75f;

	private bool startDelayed;

	private LightningStream currentLS;

	private float hitInterval = 0.0825f;

	private Vector2 currentPosition;

	public bool isEmpowered;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/ThrownItems/ThunderAnchor.prefab"));

	public override void Start()
	{
		base.Start();
		lifeStopwatch.SetDelay(lifeTime, stopCurrent: false, autoStart: true);
		if (isEmpowered)
		{
			burstCount = 7;
		}
	}

	public override void FixedUpdate()
	{
		if (!lifeStopwatch.IsRunning && gameObject != null)
		{
			Object.Destroy(gameObject);
		}
		else if (throwComplete)
		{
			switch (ChaosStopwatch.CheckInterval(burstStopwatchID))
			{
			case StopwatchState.Ready:
				ShootLightningStream();
				break;
			case StopwatchState.Done:
				if (currentLS == null && gameObject != null)
				{
					LightningBurst.CreateBurst(transform.position + Vector3.up, string.Empty, string.Empty);
					Object.Destroy(gameObject);
				}
				break;
			}
		}
		else
		{
			base.FixedUpdate();
			spriteTrans.transform.localEulerAngles = Vector3.Lerp(startRotation, endRotation, PercentComplete);
		}
	}

	private void LateUpdate()
	{
		if (!throwComplete && spriteRenderer != null)
		{
			spriteRenderer.sortingLayerName = ((!(heightLerpValue > 2f)) ? "Actor" : "UI");
		}
	}

	public override void OnLanding()
	{
		currentPosition = transform.position;
		destroyAfterLanding = !Globals.CheckCircle(currentPosition, 0.25f, ChaosCollisions.layerPit);
		LightningBurst.CreateBurst(currentPosition, string.Empty, string.Empty);
		Globals.ChaosInst<LightningStrike>(LightningStrike.Prefab, null, currentPosition);
		base.OnLanding();
		if (!destroyAfterLanding)
		{
			burstStopwatchID = ChaosStopwatch.Begin((!startDelayed) ? 0f : burstDelay, useInterval: true, burstDelay, burstCount);
		}
	}

	public override void ThrowToTargetVector(Vector2 givenPosition)
	{
		base.ThrowToTargetVector(givenPosition);
		targetPosition += positionOffset;
		reverseRotation = givenPosition.x > transform.position.x;
		if (reverseRotation)
		{
			rotationCount = 0f - rotationCount;
		}
		startRotation = Vector3.zero;
		endRotation = Vector3.zero;
		endRotation.z += 360f * rotationCount;
	}

	public void SetParentInfo(Transform givenTrans, Health givenHealth)
	{
		parentTrans = givenTrans;
		parentHealth = givenHealth;
	}

	public void SetSkillInfo(string givenCategory, string givenID)
	{
		skillCat = givenCategory;
		skillID = givenID;
	}

	public void SetBurstInfo(int givenCount, float givenDelay, bool givenStart = true)
	{
		burstCount = givenCount;
		burstDelay = givenDelay;
		startDelayed = givenStart;
	}

	private void ShootLightningStream()
	{
		currentPosition = transform.position;
		if (parentTrans == null || parentHealth == null || parentHealth.CurrentHealthValue <= 0)
		{
			ChaosStopwatch.Stop(burstStopwatchID);
		}
		else if (!(Vector2.Distance(currentPosition, parentTrans.position) > maxDistance) && Entity.HasLineOfSight(currentPosition, parentTrans.position, maxDistance, ChaosCollisions.layerUpperWallAndObst))
		{
			currentLS = Globals.ChaosInst<LightningStream>(LightningStream.Prefab, transform.parent, streamTrans.position);
			currentLS.targetTrans = parentTrans;
			currentLS.attack.SetAttackInfo(skillCat, skillID);
			currentLS.hitInterval = hitInterval;
		}
	}
