		private void CreateX(float givenDist, float givenSpeed, Vector2 givenOffset, bool useBurst = false)
		{
			calcTime = givenDist / givenSpeed;
			perpendVec = Globals.GetPerpendicular(targetVector);
			leftVec = (targetVector + perpendVec).normalized;
			rightVec = (targetVector - perpendVec).normalized;
			perpendVec *= givenDist;
			leftStrike = CreateStrike(currentPosition + givenOffset - perpendVec, leftVec, givenSpeed);
			rightStrike = CreateStrike(currentPosition + givenOffset + perpendVec, rightVec, givenSpeed);
			leftStrike.InitStrike(rightStrike, leftVec, rightVec, calcTime, targetVector);
			rightStrike.InitStrike(leftStrike, rightVec, leftVec, calcTime, targetVector, useBurst, burstLevel, burstScale);
		}

		private LightningXStrike CreateStrike(Vector2 givenPosition, Vector2 givenVector, float givenSpeed)
		{
			currentLX = (LightningXStrike)CreateProjectile(LightningXStrike.Prefab, givenPosition, Globals.GetRotationQuaternion(givenVector));
			currentLX.attackBox.knockbackOverwriteVector = targetVector;
			currentLX.moveSpeed = givenSpeed;
			return currentLX;
		}
