using UnityEngine;

public class LightningXStrike : Projectile
{
	private static GameObject prefab;

	private LightningXStrike otherXStrike;

	private Vector2 mainVec;

	private Vector2 altVec;

	private bool useMainVec = true;

	private bool useBurst;

	private int burstLevel = 2;

	private float burstScale = 1f;

	private Vector2 kbVector;

	private ChaosQuickStopwatch flipStopwatch = new ChaosQuickStopwatch();

	private Vector2 currentPosition;

	private int maxBounceCount = 4;

	private int bounceCounter;

	private bool resetQueued;

	private bool resetExec;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/LightningXStrikeObject.prefab"));

	public void InitStrike(LightningXStrike givenOther, Vector2 givenMain, Vector2 givenAlt, float givenTime, Vector2 givenKB, bool givenBurst = false, int givenLevel = 2, float givenScale = 1f)
	{
		otherXStrike = givenOther;
		moveVector = givenMain;
		mainVec = givenMain;
		altVec = givenAlt;
		flipStopwatch.SetDelay(givenTime);
		flyTime = givenTime * ((float)maxBounceCount * 1.95f);
		useBurst = givenBurst;
		burstLevel = givenLevel;
		burstScale = givenScale;
		kbVector = givenKB;
	}

	public override void Start()
	{
		base.Start();
		PlayParticleEffect();
		flipStopwatch.IsRunning = true;
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (otherXStrike == null)
		{
			resetExec = true;
			ResetProjectile();
		}
		else
		{
			if (flipStopwatch.IsRunning)
			{
				return;
			}
			flipStopwatch.IsRunning = true;
			useMainVec = !useMainVec;
			moveVector = ((!useMainVec) ? altVec : mainVec);
			SoundManager.PlayAudioWithDistance("ThunderKnock", transform.position);
			if (useMainVec)
			{
				PlayParticleEffect();
				return;
			}
			bounceCounter++;
			if (useBurst)
			{
				CreateBurst();
			}
			else
			{
				PlayParticleEffect();
			}
			goThroughWalls = bounceCounter > 1;
			if (resetQueued)
			{
				resetExec = true;
				ResetProjectile();
			}
		}
	}

	public override void ResetProjectile()
	{
		resetQueued = true;
		if (!resetExec)
		{
			RefreshFlightTime(flyTimeOnly: true);
			return;
		}
		base.ResetProjectile();
		PlayParticleEffect(isReset: true);
	}

	private void CreateBurst()
	{
		if (!(otherXStrike == null))
		{
			currentPosition = (otherXStrike.transform.position + transform.position) * 0.5f;
			LightningBurst.CreateBurst(currentPosition + kbVector, attackBox.GetAtkInfoAtLevel(burstLevel), burstScale).attack.knockbackOverwriteVector = kbVector;
			PlayParticleEffect();
		}
	}

	private void PlayParticleEffect(bool isReset = false)
	{
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit((!isReset) ? 3 : 5, transform.position);
	}
}
