using UnityEngine;

public class ShockLine : Projectile
{
	private static GameObject prefab;

	private Transform spriteTransLeft;

	private Transform spriteTransRight;

	private BoxCollider2D wallCol;

	private BoxCollider2D atkCol;

	private ParticleSystem partSys;

	private ParticleSystem.ShapeModule partSysShapeMod;

	private ParticleSystem.EmissionModule partSysEmitMod;

	private bool isMoving = true;

	private float originalMoveSpeed = 10f;

	public float expandTime = 0.5f;

	private int expandStopwatchID;

	private float expandPercentage = 1f;

	private bool isExpanding = true;

	public float startWidth = 1f;

	public float endWidth = 4f;

	private float halfWidth = 1f;

	private float currentWidth;

	private float lerpValue;

	private Vector2 calcVector;

	private int attackStopwatchID;

	public float attackInterval = 0.5f;

	protected ParticleEffect lightningAuraEffect0;

	protected ParticleEffect lightningAuraEffect1;

	private AudioSource lineAudio;

	public int finalAtkLevel = 2;

	public bool playAudio = true;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ShockLine.prefab"));

	public override void Awake()
	{
		base.Awake();
		spriteTransLeft = transform.Find("LightningCoreLeft");
		spriteTransRight = transform.Find("LightningCoreRight");
		wallCol = transform.Find("WallCollider").GetComponent<BoxCollider2D>();
		atkCol = transform.Find("AttackBox").GetComponent<BoxCollider2D>();
		partSys = transform.Find("Emitter").GetComponent<ParticleSystem>();
		partSysShapeMod = partSys.shape;
		partSysEmitMod = partSys.emission;
	}

	public override void Start()
	{
		base.Start();
		originalMoveSpeed = moveSpeed;
		expandStopwatchID = ChaosStopwatch.Begin(expandTime);
		attackStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, attackInterval, Mathf.CeilToInt(flyTime / attackInterval));
		lightningAuraEffect0 = PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect");
		lightningAuraEffect0.reqFollowTrans = true;
		lightningAuraEffect0.Play(8f, followTransform: spriteTransLeft, position: null, overrides: LightningAuraEffect.SmallAuraOverride);
		lightningAuraEffect1 = PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect");
		lightningAuraEffect1.reqFollowTrans = true;
		lightningAuraEffect1.Play(8f, followTransform: spriteTransRight, position: null, overrides: LightningAuraEffect.SmallAuraOverride);
		partSysEmitMod.rateOverTime = endWidth * 20f;
		SoundManager.PlayAudioWithDistance("BallLightningEnd", transform.position, null, 24f, -1f, 0.85f);
	}

	public override void Update()
	{
		base.Update();
		if (playAudio)
		{
			lineAudio = SoundManager.PlayIfNotPlaying("BallLightningLoop", lineAudio, transform, useStdPitchOverride: true, 0.8f);
		}
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		StopwatchState stopwatchState = ChaosStopwatch.CheckInterval(attackStopwatchID);
		if (stopwatchState == StopwatchState.Ready)
		{
			atkCol.enabled = false;
		}
		else
		{
			atkCol.enabled = true;
		}
		if (isMoving || isExpanding)
		{
			expandPercentage = 1f - ChaosStopwatch.GetTimePercentage(expandStopwatchID);
			lerpValue = (1f - expandPercentage * expandPercentage) * 2f;
			if (isMoving)
			{
				moveSpeed = Mathf.Lerp(originalMoveSpeed, 0f, lerpValue);
				isMoving = lerpValue < 1f;
			}
			if (isExpanding)
			{
				currentWidth = Mathf.Lerp(startWidth, endWidth, lerpValue);
				halfWidth = currentWidth * 0.5f;
				calcVector = Vector2.zero;
				calcVector.x = 0f - (halfWidth + 0.125f);
				spriteTransLeft.localPosition = calcVector;
				calcVector.x = halfWidth + 0.125f;
				spriteTransRight.localPosition = calcVector;
				calcVector.x = currentWidth;
				calcVector.y = 0.5f;
				wallCol.size = calcVector;
				atkCol.size = calcVector;
				partSysShapeMod.radius = halfWidth;
				isExpanding = lerpValue < 1f;
			}
			if (lerpValue >= 1f)
			{
				attackBox.ChangeAttackInfoLevel(finalAtkLevel);
			}
		}
	}

	public override bool CheckMaxLifeTime()
	{
		if (ChaosStopwatch.Check(lifeStopwatchID))
		{
			ResetProjectile();
			return true;
		}
		return false;
	}

	public override void HandleWallCollision(Collider2D other)
	{
		isMoving = false;
		moveSpeed = 0f;
		goThroughWalls = true;
		base.HandleCollision(other);
	}

	public void StopLerp()
	{
		isMoving = false;
		moveSpeed = 0f;
		isExpanding = false;
	}

	public override void ResetProjectile()
	{
		lightningAuraEffect0.Stop();
		lightningAuraEffect1.Stop();
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(4, spriteTransLeft.position, LightningAuraEffect.SmallAuraOverride);
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(4, spriteTransRight.position, LightningAuraEffect.SmallAuraOverride);
		base.ResetProjectile();
	}
}

