	if (ChaosStopwatch.Check(lifeStopwatchID) || flagForReset)
	{
		ResetProjectile();
		return true;
	}
	return false;
}

public virtual void Update()
{
	if (!shootAnnounced && moveSpeed > 0f && moveVector != Vector2.zero && projectileShootEvent != null)
	{
		projectileShootEvent(this);
		shootAnnounced = true;
	}
	if (CheckMaxLifeTime())
	{
		return;
	}
	if (ChaosStopwatch.Check(flyStopwatchID))
	{
		if (!boomerang)
		{
			ResetProjectile();
			return;
		}
		if (parentObject == null)
		{
			boomerang = false;
			Debug.Log(gameObject.name + " has no parent, but is set to boomerang.");
			return;
		}
		if (!boomerangReturning)
		{
			boomerangReturning = true;
			OnBoomerangReturn();
			return;
		}
		if (attackBox != null && resetAttackOnBoomerangReturn)
		{
			attackBox.gameObject.SetActive(value: true);
		}
		HandleBoomerang();
	}
	if (boomerangReturning && (parentObject == null || Vector2.Distance(transform.position, parentObject.transform.position) < returningSnapDistance))
	{
		ResetProjectile();
	}
}

public virtual void FixedUpdate()
{
	if (updateVelocity)
	{
		rigidbody2D.velocity = moveVector * moveSpeed;
	}
	HandleRotation();
	HandlePointTowardMoveVector();
}

public virtual void HandleRotation()
{
	if (rotation)
	{
		projectileSprite.transform.Rotate(rotationVector * Time.fixedDeltaTime);
	}
}

public void HandlePointTowardMoveVector()
{
	if (pointTowardMoveVector && moveVector != Vector2.zero && !isPointedAtMoveVector)
	{
		Vector2 targetPosition = ((!flipPointTowardMoveVector) ? ((Vector2)transform.position + moveVector) : ((Vector2)transform.position - moveVector));
		RotateTowardsTarget(targetPosition);
		isPointedAtMoveVector = true;
	}
	if (pointTowardMoveVector && isPointedAtMoveVector && !visualsOn)
	{
		Show();
	}
}

public bool IsParentObject(GameObject other)
{
	Entity componentInParent = other.GetComponentInParent<Entity>();
	return other == parentObject || other.transform.parent.gameObject == parentObject || (componentInParent != null && componentInParent.skillCategory == attackBox.atkInfo.skillCategory) || (parentEntity != null && componentInParent == parentEntity);
}

public virtual void OnTriggerEnter2D(Collider2D other)
{
	HandleProjectileCollision(other);
}

public virtual void HandleProjectileCollision(Collider2D other)
{
	colProj = other.GetComponentInParent<Projectile>();
	if (!(colProj == null) && !ignoreProjectileCollisions && !colProj.ignoreProjectileCollisions && !collidedProjectiles.Contains(colProj) && attackBox.atkInfo != null && colProj.attackBox.atkInfo != null && !(attackBox.atkInfo.skillCategory == colProj.attackBox.atkInfo.skillCategory) && (GameController.pvpOn || !(parentEntity is Player) || !(colProj.parentEntity is Player)))
	{
		OnProjectileCollision(other, colProj);
		if (globalProjectileCollisionEvents != null)
		{
			globalProjectileCollisionEvents(this, colProj);
		}
