					currentSeeker.SetTransforms(parentTrans, parentTrans, parent.playerSummonsList);
				}
				else if (prevSeeker != null)
				{
					currentSeeker.SetTransforms(parentTrans, prevSeeker.transform);
				}
				prevSeeker = currentSeeker;
			}
		}

		public virtual void CreateSeeker(Vector2 givenPosition, Vector2 givenOffset)
		{
			currentSeeker = ChaosInst<Seeker>(seekerPrefab, givenPosition);
			currentSeeker.gameObject.name = seekerPrefab.name + parent.skillCategory;
			currentSeeker.attack.SetAttackInfo(parent.skillCategory, skillID, currentLevel);
			currentSeeker.isEmpowered = IsEmpowered;
			currentSeeker.ClusterID = clusterID;
			currentSeeker.SetThrowPosition(givenPosition + givenOffset);
			currentSeeker.SetDuration(duration);
			currentSeeker.startingHealth = spawnHealth;
			Seeker seeker = currentSeeker;
			seeker.onDeadEventHandlers = (Seeker.SeekerDeadEventHandler)Delegate.Remove(seeker.onDeadEventHandlers, new Seeker.SeekerDeadEventHandler(OnSeekerDead));
			Seeker seeker2 = currentSeeker;
			seeker2.onDeadEventHandlers = (Seeker.SeekerDeadEventHandler)Delegate.Combine(seeker2.onDeadEventHandlers, new Seeker.SeekerDeadEventHandler(OnSeekerDead));
			seekerList.Add(currentSeeker);
			parent.playerSummonsList.Add(currentSeeker.gameObject);
		}

		public virtual void OnSeekerDead(Seeker givenSeeker)
		{
			if (!(givenSeeker == null))
			{
				givenSeeker.onDeadEventHandlers = (Seeker.SeekerDeadEventHandler)Delegate.Remove(givenSeeker.onDeadEventHandlers, new Seeker.SeekerDeadEventHandler(OnSeekerDead));
				seekerList.Remove(givenSeeker);
				seekerList.RemoveNullValues();
				if (!SeekersActive)
				{
					StartCooldownTimer();
				}
			}
		}
	}

