	public class LightningMinionAttackState : State<LightningMinion>
	{
		private Vector2 atkPosition;

		private Vector2 targetPosition;

		private Vector2 targetHBPos;

		private Vector2 targetVector;

		private bool moveCompleted;

		private bool attackCompleted;

		private bool delayCompleted;

		private int delayStopwatchID;

		private LightningStream currentLS;

		public LightningMinionAttackState(string newName, FSM newFSM, LightningMinion newEnt)
			: base(newName, newFSM, newEnt)
		{
		}

		public override void OnEnter()
		{
			targetPosition = parent.closestTargetInfo.transform.position;
			targetHBPos = parent.closestTargetInfo.hurtBoxTransform.position;
			targetVector = (targetHBPos - (Vector2)parent.coreTrans.position).normalized;
			moveCompleted = false;
			attackCompleted = false;
			delayCompleted = false;
		}

		public override void Update()
		{
			if (ChaosStopwatch.Check(delayStopwatchID) && moveCompleted)
			{
				if (!attackCompleted)
				{
					attackCompleted = true;
					delayStopwatchID = ChaosStopwatch.Begin((float)parent.atkCount * parent.atkInterval);
					FireLightningStream(parent.coreTrans.position, targetPosition);
					parent.anim.Play("Attack", -1, 0f);
					CameraController.ShakeCamera(0.5f);
				}
				else if (!delayCompleted)
				{
					delayCompleted = true;
					delayStopwatchID = ChaosStopwatch.Begin(parent.atkExitTime);
					parent.movement.moveVector = -targetVector;
					parent.movement.MoveToMoveVector(parent.movement.dashSpeedStat.CurrentValue);
					PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(8, parent.coreTrans.position);
					parent.anim.Play("Idle", -1, 0f);
					CameraController.ShakeCamera(0.25f);
				}
				else
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
			}
		}

		public override void FixedUpdate()
		{
			if (moveCompleted)
			{
				return;
			}
			moveCompleted = parent.MoveToTargetOrFollowPath(parent.transform.position, targetPosition, parent.attackRadius, parent.attackRadius);
			if (moveCompleted)
			{
				parent.movement.EndMovement();
				delayStopwatchID = ChaosStopwatch.Begin(parent.atkWindTime);
				atkPosition = parent.coreTrans.position;
				targetPosition = Globals.GetLinecastVector(atkPosition, atkPosition + targetVector * parent.attackRadius, ChaosCollisions.layerUpperWallAndObst);
				if (parent.isEnemy)
				{
					CreateLightningWarning(atkPosition, targetPosition);
				}
			}
		}

		public override void OnExit()
		{
			if (currentLS != null)
			{
				currentLS.StopAttack();
			}
		}

		private void CreateLightningWarning(Vector2 givenStart, Vector2 givenEnd)
		{
			Globals.ChaosInst<LightningWarning>(LightningWarning.Prefab, null, givenStart).Init(givenStart, givenEnd, parent.atkWindTime);
		}

		private void FireLightningStream(Vector2 givenPosition, Vector2 givenEnd)
		{
			currentLS = Globals.ChaosInst<LightningStream>(LightningStream.Prefab, null, givenPosition);
			currentLS.targetLocation = givenEnd;
			currentLS.flipStartEndPos = true;
			currentLS.attack.SetAttackInfo(parent.skillCategory, parent.skillID, parent.skillLevel, parent.isUltimate);
			currentLS.hitCount = parent.atkCount;
			currentLS.hitInterval = parent.atkInterval;
			LightningBurst.CreateBurst(givenPosition, string.Empty, string.Empty, 1, 0.5f);
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(8, givenPosition);
		}
	}

