	public bool MoveToTargetOrFollowPath(Vector3 startPos, Vector3 targetPos, float losRange, float moveToRadius = 0f, string moveAnimName = "Run")
	{
		if (Entity.HasLineOfSight(startPos, targetPos, losRange, lineOfSightLayerMask))
		{
			ChaosStopwatch.Stop(requestPathStopwatchID);
			if (moveAnimName != string.Empty)
			{
				PlayAnimOnFaceDirChange(moveAnimName, targetPos, animFacingDirections, appendFacingDirection: false);
			}
			if (movement.MoveToTarget(targetPos, moveToRadius))
			{
				FaceTarget(targetPos, animFacingDirections);
				return true;
			}
			return false;
		}
		if (ChaosStopwatch.Check(requestPathStopwatchID))
		{
			requestPathStopwatchID = ChaosStopwatch.Begin(requestPathTime);
			followingPath = false;
			if (FindAndTraversePath(traversableNodeMap, startPos, targetPos, minNodeDist, moveAnimName, appendFacingDirection: false, animFacingDirections, startNew: true) == -1)
			{
				return true;
			}
			followingPath = true;
			return false;
		}
		if (followingPath && FindAndTraversePath(traversableNodeMap, startPos, targetPos, minNodeDist, moveAnimName, appendFacingDirection: false, animFacingDirections) != 0)
		{
			followingPath = false;
			return true;
		}
		return false;
	}

