	public class BaseWardState : SkillState
	{
		public GameObject wardPrefab;

		public Ward currentWard;

		private static float spawnRange = 3f;

		private static int maxSpawnCount = 6;

		private float duration = 1f;

		private int spawnCount = 1;

		private int healthValue = 1;

		private Vector2 currentPosition;

		private int maxPosCount;

		private int calcPosCount;

		private int offsetCount;

		private bool skipEvens;

		public override string OnEnterAnimStr => parent.GSlamAnimStr;

		public BaseWardState(string newName, FSM newFSM, Player newPlayer)
			: base(newName, newFSM, newPlayer)
		{
			isBuffSkill = true;
			isSummonSkill = true;
			SetAnimTimes(0.25f, 0.2f, 0.3f, 0.35f, 0.4f);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			ApplyStopElement();
			CameraController.ShakeCamera(0.25f);
			duration = skillData.GetValue<float>(StatData.durStr);
			spawnCount = Mathf.Min(maxSpawnCount, skillData.GetValue<int>(StatData.spawnStr));
			healthValue = skillData.GetValue<int>(StatData.healthStr);
			maxPosCount = maxSpawnCount;
			calcPosCount = spawnCount;
			skipEvens = calcPosCount % 2 == 0;
			if (skipEvens)
			{
				calcPosCount *= 2;
				maxPosCount *= 2;
			}
			offsetCount = (int)((float)calcPosCount * 0.5f);
			currentPosition = parent.transform.position;
			for (int i = -offsetCount; i <= offsetCount; i++)
			{
				if (!skipEvens || i % 2 != 0)
				{
					CreateWard(Globals.GetLinecastVector(currentPosition, currentPosition + Globals.GetRotatedCircleVector(maxPosCount, i, inputVector) * spawnRange, ChaosCollisions.layerAllWallAndObst));
				}
			}
		}

		public virtual void CreateWard(Vector2 givenPosition)
		{
			currentWard = ChaosInst<Ward>(wardPrefab, givenPosition);
			currentWard.duration = duration;
			currentWard.startingHealth = healthValue;
			currentWard.attack.SetAttackInfo(parent.skillCategory, skillID);
			currentWard.isEmpowered = IsEmpowered;
			currentWard.gameObject.name = wardPrefab.name + parent.skillCategory;
			parent.playerSummonsList.Add(currentWard.gameObject);
		}
	}

