	public static GameObject Prefab
	{
		get
		{
			if (prefab == null)
			{
				prefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/LightningFistBasic.prefab");
			}
			return prefab;
		}
	}

	public void Initialize(int givenLevel, bool givenBurst)
	{
		useBurst = givenBurst;
		if (givenLevel == 3)
		{
			hitCount = 5;
			hitInterval = 0.125f;
			transform.localScale *= 1.5f;
			if (useBurst)
			{
				negateScript.enabled = true;
				negateScript.skillCategory = attack.atkInfo.skillCategory;
			}
		}
	}

	public override void Start()
	{
		base.Start();
		endAnimTime = ((!useBurst) ? 1f : 0.5f);
		transform.localEulerAngles = new Vector3(0f, 0f, Random.Range(0f, 360f));
		PlayEffects();
		CameraController.ShakeCamera(0.15f);
	}

	private void FixedUpdate()
	{
		if (!destroyQueued && burstStarted)
		{
			switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
			{
			case StopwatchState.Running:
				attackCol.enabled = true;
				break;
			case StopwatchState.Ready:
				attackCol.enabled = false;
				burstEffect.Emit(emitCount);
				PlayEffects();
				break;
			case StopwatchState.Done:
				burstEffect.transform.SetParent(null);
				Object.Destroy(burstEffect.gameObject, 0.5f);
				EndAttack();
				break;
			}
		}
	}

	public override void EndAttack()
	{
		if (useBurst && !burstStarted)
		{
			CameraController.ShakeCamera(0.25f);
			burstStarted = true;
			hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, hitCount);
			burstEffect.Emit(emitCount);
			PlayEffects();
			attackCol.enabled = false;
			attack.transform.localScale *= 1.125f;
			attack.ChangeAttackInfoLevel(4);
			useAnimTime = false;
			useLifeTime = true;
			lifeStopwatchID = ChaosStopwatch.Begin(hitInterval * (float)hitCount + 0.5f);
		}
		else
		{
			destroyQueued = true;
			base.EndAttack();
		}
	}

	private void PlayEffects()
	{
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(8, transform.position, ParticleEffectOverrides.Radius0p5);
		string text = "LightningBurst";
		Vector2? soundOrigin = transform.position;
		float overridePitch = Random.Range(0.85f, 1.15f);
		SoundManager.PlayAudioWithDistance(text, soundOrigin, null, 24f, -1f, overridePitch);
	}
