	public override void ExecuteSkill()
	{
		if (!CancelToDash(enableButtonHeld: true))
		{
			if (!skillAnnounced)
			{
				skillAnnounced = true;
				base.ExecuteSkill();
				skillExecuted = false;
			}
			if (targetList.Count == 0)
			{
				parent.movement.EndMovement();
				skillExecuted = true;
			}
			else if (!slamStarted)
			{
				slamStarted = true;
				InitAnimTimes();
				startPos = parent.transform.position;
				parent.movement.EndMovement();
				parent.anim.Play(parent.GSlamAnimStr, -1, 0.1f);
			}
			else if (!groundAtkStarted)
			{
				groundAtkStarted = true;
				hitTimerID = ChaosStopwatch.Begin(0f, useInterval: true, 0.1f, 3);
				auraEmitter = PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect");
