		switch (ChaosStopwatch.CheckInterval(hitTimerID))
		{
		case StopwatchState.Ready:
			parent.anim.Play(parent.GSlamAnimStr, -1, animExecTime);
			CameraController.ShakeCamera(0.4f);
			if (!CreateGroundShock())
			{
				groundAtkDone = true;
				ChaosStopwatch.Stop(hitTimerID);
			}
			break;
		case StopwatchState.Done:
			groundAtkDone = true;
			if (IsEmpowered)
			{
				CreateThunderBlast();
			}
			break;
		}
	}

	private void OnTargetHit(Entity givenEnt)
	{
		if (!(givenEnt == null) && !(givenEnt is Destructible) && !targetList.Contains(givenEnt.transform))
		{
			if (!targetHit)
			{
				targetHit = true;
				skillExecuted = false;
			}
			targetList.Add(givenEnt.transform);
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		targetList.Clear();
		if (auraEmitter != null)
		{
