		{
			Attack attack = curWhip.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			UnityEngine.Object.Destroy(curWhip.gameObject);
			curWhip = null;
		}
	}

	private void CreateThunderBlast()
	{
		targetExists = false;
		for (int i = 0; i < targetList.Count; i++)
		{
			if (!(targetList[i] == null) && !(targetList[i].gameObject == null) && !(targetList[i].transform == null))
			{
				if (!targetExists)
				{
					targetExists = true;
				}
				targetPos = targetList[i].position;
				curBlast = ChaosInst<ThunderBlast>(ThunderBlast.Prefab, targetPos);
				curBlast.SetSkillData(parent.skillCategory, skillID, 4);
				curBlast.knockbackOverwriteVector = (startPos - targetPos).normalized;
				curBlast.delayTime = 0.15f;
				curBlast.atkRadius = 1.25f;
				curBlast.knockbackMultiplierOverride = Mathf.Lerp(10f, 50f, Mathf.Clamp01(Vector2.Distance(startPos, targetPos) * 0.1f));
			}
		}
	}

	private bool CreateGroundShock()
	{
		targetExists = false;
		for (int i = 0; i < targetList.Count; i++)
		{
			if (!(targetList[i] == null) && !(targetList[i].gameObject == null) && !(targetList[i].transform == null))
			{
				if (!targetExists)
				{
					targetExists = true;
				}
				targetPos = targetList[i].position + (Vector3)UnityEngine.Random.insideUnitCircle * 0.3f;
				curStrike = ChaosInst<LightningStrike>(LightningStrike.Prefab, targetPos);
				curStrike.spriteRenderer.sortingLayerName = "TargetLineAir";
				CreateStream();
				LightningBurst.CreateBurst(targetPos, parent.skillCategory, skillID, 3);
			}
		}
		return targetExists;
	}

	private void CreateStream()
	{
		streamDist = Vector2.Distance(startPos, targetPos) * 0.4f;
		streamVec = (targetPos - startPos).normalized;
		streamOffset = (streamVec + (Vector3)Globals.GetPerpendicular(streamVec, Globals.RandBool) * 0.2f).normalized;
		ref Vector3 reference = ref streamVecs[0];
		reference = startPos;
		ref Vector3 reference2 = ref streamVecs[1];
		reference2 = startPos + streamOffset * streamDist;
		ref Vector3 reference3 = ref streamVecs[2];
		reference3 = targetPos - streamOffset * streamDist;
		ref Vector3 reference4 = ref streamVecs[3];
		reference4 = targetPos;
		for (int i = 0; i < streamVecs.Length - 1; i++)
		{
			LightningStream.Create(streamVecs[i], streamVecs[i + 1], string.Empty, string.Empty, 0);
		}
